{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Nomegestrol acetate, the closest retrieved analogue and a 19-norprogesterone 17-acetate, has an absolute oral bioavailability of 63.4% in healthy women, directly supporting F ≥ 20% for the query's 19-norprogesterone acetate scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Chlormadinone acetate, a structurally related 17-acetoxy progestin, shows approximately 100% oral bioavailability in humans, supporting high absorption for this steroid acetate class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Cyproterone acetate, another 17-acetoxy progestin, has almost complete absolute oral bioavailability (88%), reinforcing that 17-acetoxy progestins generally exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Norethisterone acetate, a 19-nor steroid acetate, has an absolute oral bioavailability of about 64%, supporting high F for the 19-nor acetate series.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Medroxyprogesterone acetate, a C19-methylated 17-acetoxy progestin, has low oral bioavailability (<10-15%) in humans; this is contradictory evidence but less transferable because the query is 19-nor and lacks MPA's specific first-pass liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Abiraterone acetate, a 3β-acetoxy androstane prodrug, has <10% oral bioavailability; this is contradictory but structurally distant from the 19-norprogesterone 17-acetate query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the query is a 19-norprogesterone 17-acetate; the closest analogue NOMAC and several other 17-acetoxy progestins have absolute oral bioavailability of 63-100%, while the low-bioavailability analogues are structurally more distant (C19-methylated MPA, androstane abiraterone acetate).",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present in the retrieved evidence.",
    "The influence of the 11β-(4-dimethylaminophenyl) substituent on first-pass metabolism and absorption is not directly represented by any single analogue.",
    "Dose, formulation, and food effects could shift oral bioavailability, but the threshold is broad (≥20%)."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

